      SUBROUTINE MRVRC2CC     MULTIPLIES RV AND RC2 AND ADDS RESULT TO R2VCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'R.CIN'      INCLUDE 'R2VS.CIN'      INCLUDE 'RC2.CIN'      INCLUDE 'RC2S.CIN'      INCLUDE 'RS.CIN'      INCLUDE 'R2P.CIN'      INCLUDE 'T.CIN'      INCLUDE 'TC2.CIN'      INCLUDE 'TC2S.CIN'      INCLUDE 'TS.CIN'      INCLUDE 'U.CIN'      INCLUDE 'U2VS.CIN'      INCLUDE 'UC2.CIN'      INCLUDE 'UC2S.CIN'      INCLUDE 'US.CIN'CC---------------------------------------------------------      IF (R2P) GO TO 50      DO 10 JK = 1, 36   10 R2VSL(JK,NV2) = RVL(JK)      IF (NORD2 .GE. 2) THEN        DO 20 JKM = 1, 105   20   T2VL(JKM,NV2) = TVL(JKM)      ENDIF      IF (NORD2 .GE. 3) THEN        DO 30 JKLM = 1, 280   30   U2VL(JKLM,NV2) = UVL(JKLM)      ENDIF      GO TO 200C   50 IF (NORD2 .EQ. 1) THEN        CALL CAB(RS,RV,RC2)      ELSE IF (NORD2 .EQ. 2) THEN        CALL CAB2(RS,TS,RV,TV,RC2,TC2)      ELSE IF (NORD2 .EQ. 3) THEN        CALL CAB3(RS,TS,US,RV,TV,UV,RC2,TC2,UC2)      ENDIF      IF (R2VP(NV2)) GO TO 100C      DO 60 JK = 1, 36   60 R2VSL(JK,NV2) = RSL(JK)      IF (NORD2 .GE. 2) THEN        DO 70 JKM = 1, 105   70   T2VL(JKM,NV2) = TSL(JKM)      ENDIF      IF (NORD2 .GE. 3) THEN        DO 80 JKLM = 1, 280   80   U2VL(JKLM,NV2) = USL(JKLM)      ENDIF      GO TO 200C  100 DO 110 JK = 1, 36  110 R2VSL(JK,NV2) = R2VSL(JK,NV2) + RSL(JK)      IF (NORD2 .GE. 2) THEN        DO 120 JKM = 1, 105  120   T2VL(JKM,NV2) = T2VL(JKM,NV2) + TSL(JKM)      ENDIF      IF (NORD2 .GE. 2) THEN        DO 130 JKLM = 1, 280  130   U2VL(JKLM,NV2) = U2VL(JKLM,NV2) + USL(JKLM)      ENDIFC  200 RETURN      END